package com.footballacademy.model;
import jakarta.persistence.*;
@Entity @Table(name="scouting_criteria", indexes={@Index(name="idx_criterion_domain", columnList="domain"),@Index(name="idx_criterion_active", columnList="active")})
public class ScoutingCriterion { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false) private String name; private String domain; private Double weight=1.0; @Column(length=1000) private String description; private Boolean active=true; public boolean isTechnical(){return domain!=null&&domain.equalsIgnoreCase("TECHNICAL");} public Long getId(){return id;} public void setId(Long id){this.id=id;} public String getName(){return name;} public void setName(String name){this.name=name;} public String getDomain(){return domain;} public void setDomain(String domain){this.domain=domain;} public Double getWeight(){return weight;} public void setWeight(Double weight){this.weight=weight;} public String getDescription(){return description;} public void setDescription(String description){this.description=description;} public Boolean getActive(){return active;} public void setActive(Boolean active){this.active=active;} }
